      "success_rate": "high"
    },
    {
      "pattern": "Internalization of Search into Chain-of-Thought",
      "description": "Rather than using external tree search algorithms (MCTS, BFS, beam search) that scale poorly and add engineering complexity, internalize the search process into the model's own generation via structured thinking patterns that interleave informal reasoning with formal code. This enables scaling with model size for the first time in theorem proving and dramatically improves sample efficiency.",
      "examples": ["Kimina-Prover"],
      "success_rate": "medium"
    },
    {
      "pattern": "Recursive (Not Flat) Decomposition",
      "description": "Single-layer decomposition (Draft-Sketch-Prove style) hits a ceiling because some subgoals are still too hard. Recursive decomposition — where any unsolved subgoal triggers another round of informal reasoning, formalization, and decomposition — overcomes this ceiling by ensuring no subgoal is 'too hard' as long as it can be atomized. Performance jumps dramatically from depth 0 to depth 2+.",
      "examples": ["Hilbert"],
      "success_rate": "high"
    },
    {
      "pattern": "Distillation from Large to Small via Verified Rollouts",
      "description": "Train a massive model (72B-671B) with RL using verifier rewards, then distill its successful proof rollouts into a much smaller model (1.5B-7B) via SFT. The formal verification provides perfect labeling quality — no human annotation noise — making distillation unusually effective. Multiple teams independently converge on this pattern.",
      "examples": ["DeepSeek-Prover-V2", "Kimina-Prover", "Goedel-Prover-V2"],
      "success_rate": "high"
    }
  ],
  "reviewer_preferences": [
