      "impact_if_solved": "medium"
    }
  ],
  "untried_combinations": [
    {
      "idea_sketch": "Recursive decomposition (Hilbert) + RL self-improvement loop (AlphaProof/DeepSeek-Prover-V2): Use Hilbert-style recursive decomposition to generate massive amounts of hierarchically structured proof data (problem → subgoals → sub-subgoals → atomic proofs), then use these as RL training signal to teach a single model to internalize the recursive decomposition strategy, creating a self-improving loop where better decomposition generates harder training data which improves decomposition ability.",
      "from_papers": ["Hilbert", "AlphaProof", "DeepSeek-Prover-V2"],
