      "from_papers": ["Hilbert", "Goedel-Prover-V2"],
      "why_promising": "Hilbert shows that reasoner quality matters more than prover quality, and Goedel-Prover-V2 shows that diversity collapse is a major issue. Multi-agent debate would increase the diversity of proof strategies explored at inference time without the diversity collapse problems of RL training. The formal verifier provides a perfect adjudicator, resolving the key challenge of debate systems (who judges?)."
    }
  ],
  "method_building_blocks": [
    {
